  ('f40c4150-202d-4508-a737-08d3511cf65a'::uuid, 'https://audio.bigmooneducation.com/b6/b6be443fd0549c7a63d0d440aec0eb05e2f36076e394591fd4605466da6b4869.mp3'),
  ('f5692792-8b1e-48ea-95d2-8895bbbebc14'::uuid, 'https://audio.bigmooneducation.com/1f/1f03aa000c810d4fe67fffcca198e4ce85f44f27403d0821bb892a98283f431e.mp3'),
  ('3ef44e8b-7d2f-45f6-94bf-5ed5e1ea8af5'::uuid, 'https://audio.bigmooneducation.com/e5/e56df5fef7f3a84ef486932c57c432d87b8c85f3e2bfa258b7ed6fa1d4a57495.mp3')
  ) AS v(id, audio_url)
 WHERE w.id = v.id;

-- ② 例句音频:本批无

SELECT 'AFTER' AS stage,
       (SELECT count(*) FROM vocab_words    WHERE audio_url IS NOT NULL) AS word_audio,
       (SELECT count(*) FROM vocab_examples WHERE audio_url IS NOT NULL) AS example_audio;

-- ── count-validate:五行都必须是 t,否则 ROLLBACK ──
SELECT 'word_audio = 2061' AS expect,
       (SELECT count(*) FROM vocab_words WHERE audio_url IS NOT NULL) = 2061 AS ok
UNION ALL
SELECT 'example_audio = 0',
       (SELECT count(*) FROM vocab_examples WHERE audio_url IS NOT NULL) = 0
UNION ALL
SELECT 'no word left without audio (in all)',
       NOT EXISTS (
         SELECT 1 FROM vocab_words w
           JOIN vocab_word_banks wb ON wb.word_id = w.id
           JOIN vocab_banks b ON b.id = wb.bank_id AND b.code = 'all'
          WHERE w.def_zh IS NOT NULL AND w.audio_url IS NULL
       )
UNION ALL
-- 例句侧的完整性,与上面词侧对称。少了这条,例句漏配也能一路绿灯过去。
SELECT 'no example left without audio (in all)',
       NOT EXISTS (
         SELECT 1 FROM vocab_examples e
           JOIN vocab_words w ON w.id = e.word_id
           JOIN vocab_word_banks wb ON wb.word_id = w.id
           JOIN vocab_banks b ON b.id = wb.bank_id AND b.code = 'all'
          WHERE e.audio_url IS NULL
       )
UNION ALL
-- 全部指向 CDN 且是内容寻址路径,防止回填进半成品/空串。
SELECT 'every audio_url is a well-formed CDN url',
       NOT EXISTS (
         SELECT 1 FROM vocab_examples
          WHERE audio_url IS NOT NULL
            AND audio_url !~ '^https://audio\.bigmooneducation\.com/[0-9a-f]{2}/[0-9a-f]{64}\.mp3$'
       );

COMMIT;
